dashboard.definition:
{
 "title": "Host 360",
 "description": "One machine, four tabs: activity and baseline deviation, peer map, process attribution, configuration history.",
 "visualizations": {
  "hdr": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "## Host 360 — $tk_host$\nEverything the firewall knows about one machine, in four tabs.",
    "fontSize": "large",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "kpi_total": {
   "type": "splunk.singlevalue",
   "title": "Connections",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('total') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#dbe0e6"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_blocked": {
   "type": "splunk.singlevalue",
   "title": "Blocked",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('blocked') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#e5484d"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_pct": {
   "type": "splunk.singlevalue",
   "title": "Blocked ratio",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('blocked_pct') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 1,
    "majorColor": "> majorValue | rangeValue(majorColorConfig)",
    "unit": "%",
    "unitPosition": "after"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "majorColorConfig": [
     {
      "to": 5,
      "value": "#2fb67c"
     },
     {
      "from": 5,
      "to": 25,
      "value": "#f5a623"
     },
     {
      "from": 25,
      "value": "#e5484d"
     }
    ]
   }
  },
  "kpi_peers": {
   "type": "splunk.singlevalue",
   "title": "Peers",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('peers') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#4fa3ff"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_ext": {
   "type": "splunk.singlevalue",
   "title": "External peers",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('ext_peers') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#f5a623"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_out": {
   "type": "splunk.singlevalue",
   "title": "Dropped volume",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('dropped_kb') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 1,
    "majorColor": "#31c2c9",
    "unit": "KB",
    "unitPosition": "after"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "Windows records a packet size only for packets it drops. Allowed connections carry no byte count."
  },
  "hdr_state": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Firewall posture",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_state": {
   "type": "splunk.table",
   "title": "Last known state",
   "dataSources": {
    "primary": "ds_state"
   },
   "options": {
    "count": 3,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "columnFormat": {
     "state": {
      "rowBackgroundColors": "> table | seriesByName(\"state\") | matchValue(stateBgConfig)"
     }
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "scopeBgConfig": [
     {
      "match": "external",
      "value": "#3a2c17"
     },
     {
      "match": "internal",
      "value": "#16262f"
     }
    ],
    "stateBgConfig": [
     {
      "match": "enabled",
      "value": "#14301f"
     },
     {
      "match": "disabled",
      "value": "#4a1015"
     }
    ],
    "severityBgConfig": [
     {
      "match": "critical",
      "value": "#4a1015"
     },
     {
      "match": "high",
      "value": "#3a1d20"
     },
     {
      "match": "medium",
      "value": "#3a2c17"
     },
     {
      "match": "informational",
      "value": "#1c2229"
     }
    ],
    "compliantBgConfig": [
     {
      "match": "true",
      "value": "#14301f"
     },
     {
      "match": "false",
      "value": "#4a1015"
     }
    ]
   }
  },
  "viz_posture_now": {
   "type": "splunk.table",
   "title": "Current posture (add-on)",
   "dataSources": {
    "primary": "ds_posture_now"
   },
   "options": {
    "count": 4,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "columnFormat": {
     "compliant": {
      "rowBackgroundColors": "> table | seriesByName(\"compliant\") | matchValue(compliantBgConfig)"
     }
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "scopeBgConfig": [
     {
      "match": "external",
      "value": "#3a2c17"
     },
     {
      "match": "internal",
      "value": "#16262f"
     }
    ],
    "stateBgConfig": [
     {
      "match": "enabled",
      "value": "#14301f"
     },
     {
      "match": "disabled",
      "value": "#4a1015"
     }
    ],
    "severityBgConfig": [
     {
      "match": "critical",
      "value": "#4a1015"
     },
     {
      "match": "high",
      "value": "#3a1d20"
     },
     {
      "match": "medium",
      "value": "#3a2c17"
     },
     {
      "match": "informational",
      "value": "#1c2229"
     }
    ],
    "compliantBgConfig": [
     {
      "match": "true",
      "value": "#14301f"
     },
     {
      "match": "false",
      "value": "#4a1015"
     }
    ]
   },
   "description": "Live configuration state, from TA-windows-firewall-posture.",
   "hideWhenNoData": true,
   "containerOptions": {
    "visibility": {
     "showConditions": [
      "condition_optional"
     ],
     "showWhenConditions": "all-true"
    }
   }
  },
  "viz_timechart": {
   "type": "splunk.area",
   "title": "Activity",
   "dataSources": {
    "primary": "ds_timechart"
   },
   "options": {
    "stackMode": "stacked",
    "seriesColors": [
     "#2fb67c",
     "#e5484d",
     "#8c9199"
    ],
    "legendDisplay": "bottom",
    "yAxisTitleText": "Connections",
    "xAxisTitleText": "",
    "backgroundColor": "transparent"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "viz_bytes": {
   "type": "splunk.line",
   "title": "Volume",
   "dataSources": {
    "primary": "ds_bytes"
   },
   "options": {
    "seriesColors": [
     "#31c2c9",
     "#a175ff"
    ],
    "legendDisplay": "bottom",
    "yAxisTitleText": "Bytes",
    "xAxisTitleText": "",
    "backgroundColor": "transparent"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "hdr_base": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Behaviour vs its own baseline\nDeviation is in standard deviations from the rolling 24-hour average of distinct peers. Above 3 is worth a look.",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_baseline": {
   "type": "splunk.line",
   "title": "Distinct peers per hour vs expected",
   "dataSources": {
    "primary": "ds_baseline"
   },
   "options": {
    "seriesColors": [
     "#4fa3ff",
     "#8c9199",
     "#f5a623"
    ],
    "legendDisplay": "bottom",
    "yAxisTitleText": "",
    "xAxisTitleText": "",
    "backgroundColor": "transparent"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "hdr_who": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Who it talks to — click a peer to pivot",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_peer_graph": {
   "type": "splunk.networkGraph",
   "title": "Peer map",
   "dataSources": {
    "primary": "ds_peer_graph"
   },
   "options": {
    "layout": "force",
    "linkStyle": "c",
    "linkDirection": "one-way",
    "nodeColors": "#4fa3ff",
    "backgroundColor": "transparent",
    "nodeHorizontalPadding": 60,
    "linkValues": "> primary | seriesByName('linkValues')"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "hideWhenNoData": true
  },
  "viz_peers": {
   "type": "splunk.table",
   "title": "Remote peers",
   "dataSources": {
    "primary": "ds_peers"
   },
   "options": {
    "count": 14,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true,
    "columnFormat": {
     "scope": {
      "rowBackgroundColors": "> table | seriesByName(\"scope\") | matchValue(scopeBgConfig)"
     }
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "scopeBgConfig": [
     {
      "match": "external",
      "value": "#3a2c17"
     },
     {
      "match": "internal",
      "value": "#16262f"
     }
    ],
    "stateBgConfig": [
     {
      "match": "enabled",
      "value": "#14301f"
     },
     {
      "match": "disabled",
      "value": "#4a1015"
     }
    ],
    "severityBgConfig": [
     {
      "match": "critical",
      "value": "#4a1015"
     },
     {
      "match": "high",
      "value": "#3a1d20"
     },
     {
      "match": "medium",
      "value": "#3a2c17"
     },
     {
      "match": "informational",
      "value": "#1c2229"
     }
    ],
    "compliantBgConfig": [
     {
      "match": "true",
      "value": "#14301f"
     },
     {
      "match": "false",
      "value": "#4a1015"
     }
    ]
   },
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_peer_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_peer=$row.peer.value$",
      "newTab": false
     }
    }
   ]
  },
  "viz_services": {
   "type": "splunk.table",
   "title": "Services used",
   "dataSources": {
    "primary": "ds_services"
   },
   "options": {
    "count": 14,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "eventHandlers": [
    {
     "type": "drilldown.linkToSearch",
     "options": {
      "type": "auto",
      "newTab": true
     }
    }
   ]
  },
  "hdr_proc": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Which binary\nFrom Windows Filtering Platform audit events. Empty unless you collect Security events 5156/5157 and point the `wfo_wfp_index` macro at their index.",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   },
   "containerOptions": {
    "visibility": {
     "showConditions": [
      "condition_optional"
     ],
     "showWhenConditions": "all-true"
    }
   }
  },
  "viz_process_graph": {
   "type": "splunk.networkGraph",
   "title": "Process to external destination map",
   "dataSources": {
    "primary": "ds_process_graph"
   },
   "options": {
    "layout": "hierarchical",
    "linkStyle": "s",
    "linkDirection": "one-way",
    "nodeColors": "#a175ff",
    "backgroundColor": "transparent",
    "nodeHorizontalPadding": 60,
    "linkValues": "> primary | seriesByName('linkValues')"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "hideWhenNoData": true,
   "containerOptions": {
    "visibility": {
     "showConditions": [
      "condition_optional"
     ],
     "showWhenConditions": "all-true"
    }
   }
  },
  "viz_processes": {
   "type": "splunk.table",
   "title": "Processes generating network activity",
   "dataSources": {
    "primary": "ds_processes"
   },
   "options": {
    "count": 14,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "hideWhenNoData": true,
   "containerOptions": {
    "visibility": {
     "showConditions": [
      "condition_optional"
     ],
     "showWhenConditions": "all-true"
    }
   },
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_process_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_process=$row.process_name.value$&form.tk_host=$tk_host$",
      "newTab": false
     }
    }
   ]
  },
  "viz_listeners": {
   "type": "splunk.table",
   "title": "Processes binding or listening",
   "dataSources": {
    "primary": "ds_listeners"
   },
   "options": {
    "count": 10,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "A new listener on a workstation is rarely benign.",
   "eventHandlers": [
    {
     "type": "drilldown.linkToSearch",
     "options": {
      "type": "auto",
      "newTab": true
     }
    }
   ],
   "hideWhenNoData": true,
   "containerOptions": {
    "visibility": {
     "showConditions": [
      "condition_optional"
     ],
     "showWhenConditions": "all-true"
    }
   }
  },
  "hdr_chg": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Firewall changes on this host",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_change_timeline": {
   "type": "splunk.timeline",
   "title": "Change timeline",
   "dataSources": {
    "primary": "ds_change_timeline"
   },
   "options": {
    "backgroundColor": "transparent",
    "legendDisplay": "right",
    "category": "> primary | seriesByName('change_type')",
    "seriesColors": [
     "#2fb67c",
     "#e5484d",
     "#4fa3ff",
     "#f5a623",
     "#a175ff",
     "#31c2c9",
     "#e05f9e",
     "#8c9199"
    ]
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "One lane per change category. Bursts usually mean a policy push — or someone clearing the way.",
   "hideWhenNoData": true
  },
  "viz_changes": {
   "type": "splunk.table",
   "title": "",
   "dataSources": {
    "primary": "ds_changes_table"
   },
   "options": {
    "count": 18,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true,
    "columnFormat": {
     "severity": {
      "rowBackgroundColors": "> table | seriesByName(\"severity\") | matchValue(severityBgConfig)"
     }
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "scopeBgConfig": [
     {
      "match": "external",
      "value": "#3a2c17"
     },
     {
      "match": "internal",
      "value": "#16262f"
     }
    ],
    "stateBgConfig": [
     {
      "match": "enabled",
      "value": "#14301f"
     },
     {
      "match": "disabled",
      "value": "#4a1015"
     }
    ],
    "severityBgConfig": [
     {
      "match": "critical",
      "value": "#4a1015"
     },
     {
      "match": "high",
      "value": "#3a1d20"
     },
     {
      "match": "medium",
      "value": "#3a2c17"
     },
     {
      "match": "informational",
      "value": "#1c2229"
     }
    ],
    "compliantBgConfig": [
     {
      "match": "true",
      "value": "#14301f"
     },
     {
      "match": "false",
      "value": "#4a1015"
     }
    ]
   },
   "eventHandlers": [
    {
     "type": "drilldown.linkToSearch",
     "options": {
      "type": "auto",
      "newTab": true
     }
    }
   ]
  }
 },
 "dataSources": {
  "ds_host_list": {
   "type": "ds.search",
   "options": {
    "query": "| tstats count WHERE index IN `windows_firewall_index` sourcetype=\"windows:pfirewall\" BY host | fields host | sort host"
   },
   "name": "Host list"
  },
  "ds_traffic": {
   "type": "ds.search",
   "options": {
    "query": "`wfo_traffic` $tk_noise_raw$ | search host=\"$tk_host$\" | fields _time _raw host source sourcetype index action avg_peers bin blocked blocked_pct bytes connections current dest_ip dest_port dest_scope dest_service deviation direction dropped_bytes dropped_kb expected ext_peers f first_seen h last_seen linkValues m peer peers ports scope sd_peers service src_ip src_scope target total transport window"
   },
   "name": "Traffic for this host"
  },
  "ds_changes": {
   "type": "ds.search",
   "options": {
    "query": "`wfo_changes` | search (host=\"$tk_host$\" OR Computer=\"$tk_host$\") | fields _time _raw host source sourcetype index Computer Description EventID LocalPorts ModifyingApplication ModifyingUser Object Profiles Protocol RemotePorts RuleName SettingType SettingValue change_type changed_by direction duration firewall_state last_change profile result rule_action setting_name severity state windows_firewall_event_id"
   },
   "name": "Changes for this host"
  },
  "ds_wfp": {
   "type": "ds.search",
   "options": {
    "query": "`wfo_wfp` | search host=\"$tk_host$\" | fields _time _raw host source sourcetype index action blocked connections dest_ip dest_port dest_scope dest_service events linkValues local_port operation peers ports process_name process_path services src_port target wfp_operation"
   },
   "name": "WFP events for this host"
  },
  "ds_posture": {
   "type": "ds.search",
   "options": {
    "query": "`wfo_posture_profiles` | search Computer=\"$tk_host$\" | fields _time _raw host source sourcetype index compliant default_inbound_action enabled findings inbound log_blocked profile"
   },
   "name": "Posture for this host"
  },
  "ds_kpi": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| stats count AS total, count(eval(action=\"blocked\")) AS blocked, dc(dest_ip) AS peers, dc(eval(if(dest_scope=\"external\", dest_ip, null()))) AS ext_peers, dc(dest_port) AS ports, sum(bytes) AS dropped_bytes | eval dropped_kb = round(dropped_bytes/1024, 1), blocked_pct = if(total>0, round(blocked*100/total,1), 0)"
   },
   "name": "KPI"
  },
  "ds_state": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_changes",
    "query": "| search EventID IN (2003,2082,2083) SettingType=1 | eval firewall_state = if(SettingValue=\"01000000\",\"enabled\",\"disabled\") | stats latest(_time) AS last_change, latest(firewall_state) AS state, latest(Profiles) AS profile, latest(ModifyingUser) AS changed_by BY Computer | eval last_change = strftime(last_change, \"%F %T\")"
   },
   "name": "Firewall state"
  },
  "ds_posture_now": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_posture",
    "query": "| stats latest(enabled) AS enabled, latest(default_inbound_action) AS inbound, latest(log_blocked) AS log_blocked, latest(compliant) AS compliant, latest(findings) AS findings BY profile | sort profile"
   },
   "name": "Current posture"
  },
  "ds_timechart": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| timechart span=5m count BY action"
   },
   "name": "Activity"
  },
  "ds_bytes": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| timechart span=5m sum(bytes) AS \"Dropped bytes\""
   },
   "name": "Dropped volume"
  },
  "ds_baseline": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| bin _time span=1h | stats dc(dest_ip) AS peers, count AS connections BY _time | streamstats window=24 current=f avg(peers) AS avg_peers, stdev(peers) AS sd_peers | eval expected = round(avg_peers, 1), deviation = if(isnotnull(sd_peers) AND sd_peers>0, round((peers-avg_peers)/sd_peers, 1), 0) | fields _time peers expected deviation"
   },
   "name": "Peers vs baseline"
  },
  "ds_peer_graph": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| eval source = \"$tk_host$\", target = if(direction=\"inbound\", src_ip, dest_ip) | where isnotnull(target) | stats count AS linkValues BY source, target | sort - linkValues | head 60  | appendpipe [| stats count BY target | rename target AS source | fields source] | table source target linkValues"
   },
   "name": "Peer graph"
  },
  "ds_peers": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| eval peer = if(direction=\"inbound\", src_ip, dest_ip), scope = if(direction=\"inbound\", src_scope, dest_scope) | stats count AS connections, count(eval(action=\"blocked\")) AS blocked, dc(dest_port) AS ports, sum(bytes) AS bytes, min(_time) AS first_seen, max(_time) AS last_seen BY peer, scope | eval first_seen = strftime(first_seen, \"%F %T\"), last_seen = strftime(last_seen, \"%F %T\") | sort - connections | head 30"
   },
   "name": "Peers"
  },
  "ds_services": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| eval service = if(isnull(dest_service), \"port \".dest_port, dest_service.\" (\".dest_port.\")\") | stats count AS connections, count(eval(action=\"blocked\")) AS blocked, dc(dest_ip) AS peers BY service, transport, direction | sort - connections | head 25"
   },
   "name": "Services"
  },
  "ds_processes": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_wfp",
    "query": "| stats count AS connections, count(eval(action=\"blocked\")) AS blocked, dc(dest_ip) AS peers, dc(dest_port) AS ports, values(dest_service) AS services BY process_name | sort - connections | head 20"
   },
   "name": "Processes"
  },
  "ds_process_graph": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_wfp",
    "query": "| where dest_scope=\"external\" | stats count AS linkValues BY process_name, dest_ip | rename process_name AS source, dest_ip AS target | sort - linkValues | head 50 | appendpipe [| stats count BY target | rename target AS source | fields source] | table source target linkValues"
   },
   "name": "Process graph"
  },
  "ds_listeners": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_wfp",
    "query": "| search wfp_operation IN (\"listen allowed\",\"listen blocked\",\"bind allowed\",\"bind blocked\") | stats count AS events, values(wfp_operation) AS operation, values(src_port) AS local_port, values(process_path) AS process_path BY process_name | sort - events | head 15"
   },
   "name": "Listeners"
  },
  "ds_changes_table": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_changes",
    "query": "| search NOT EventID IN (2010,2011,2012) | lookup windows_firewall_event_id EventID OUTPUT Description | eval Object = coalesce(RuleName, setting_name, \"-\") | table _time severity result Object rule_action direction Protocol LocalPorts RemotePorts ModifyingUser ModifyingApplication | sort - _time | head 50"
   },
   "name": "Changes"
  },
  "ds_change_timeline": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_changes",
    "query": "| search NOT EventID IN (2010,2011,2012) | eval duration = 0 | table _time change_type duration severity | sort _time | head 300"
   },
   "name": "Change timeline"
  }
 },
 "inputs": {
  "input_time": {
   "type": "input.timerange",
   "title": "Time range",
   "options": {
    "token": "global_time",
    "defaultValue": "-24h@h,now"
   }
  },
  "input_host": {
   "type": "input.dropdown",
   "title": "Host",
   "dataSources": {
    "primary": "ds_host_list"
   },
   "options": {
    "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
    "token": "tk_host",
    "defaultValue": "*"
   },
   "context": {
    "formattedConfig": {
     "number": {
      "prefix": ""
     }
    },
    "formattedStatics": ">statics | formatByType(formattedConfig)",
    "statics": [
     {
      "label": "All hosts",
      "value": "*"
     }
    ],
    "label": ">primary | seriesByName(\"host\") | renameSeries(\"label\") | formatByType(formattedConfig)",
    "value": ">primary | seriesByName(\"host\") | renameSeries(\"value\") | formatByType(formattedConfig)"
   }
  },
  "input_optional": {
   "type": "input.dropdown",
   "title": "Optional sections",
   "options": {
    "token": "tk_optional",
    "defaultValue": "all",
    "items": [
     {
      "label": "Show all sections",
      "value": "all"
     },
     {
      "label": "Firewall log only",
      "value": "core"
     }
    ]
   }
  },
  "input_noise": {
   "type": "input.dropdown",
   "title": "Structural noise",
   "options": {
    "token": "tk_noise_raw",
    "defaultValue": "is_noise=0",
    "items": [
     {
      "label": "Hide broadcast / multicast / loopback",
      "value": "is_noise=0"
     },
     {
      "label": "Show everything",
      "value": "*"
     }
    ]
   }
  }
 },
